const $=s=>document.querySelector(s);const symbol=n=>`<span class="symbol" aria-hidden="true">${n}</span>`;
const uiIcon=name=>window.YolkIcons?.icon(name)||'';
const navIcon={market:'map',targets:'bookmark_added',supply:'local_gas_station',criteria:'tune',feed:'history'};
const num=(n,dec=0)=>new Intl.NumberFormat(Y.lang==='en'?'en-GB':'th-TH',{maximumFractionDigits:dec,minimumFractionDigits:dec}).format(n);
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('visible'),3600)}
const navItems=[['market','ภาพรวมประเทศ','Market map'],['targets','ทำเลที่เล็งไว้','Shortlist'],['supply','สาขา / Supply','Branches'],['criteria','เกณฑ์','Criteria'],['feed','ความเคลื่อนไหว','Activity']];
const tabTitle=r=>{let n=navItems.find(x=>x[0]===r);return n?tr(n[1],n[2]):r==='place'?tr('รายละเอียดทำเล','Location detail'):r==='poi'?tr('จัดการสาขา','Branch editor'):r==='team'?tr('ทีมและสิทธิ์','Team & roles'):tr('การแจ้งเตือน','Inbox')};
function header(){
 const settingsOpen=!!$('#header').querySelector?.('[data-header-settings]')?.open;
 const languageFocused=settingsOpen&&document.activeElement?.matches?.('[data-action="language"]');
 document.documentElement.lang=Y.lang;
 $('#sidebar').innerHTML=`<img class="landometer-identity-img sidebar-identity" src="assets/landometer-logo-horizontal-v12-889.png" width="889" height="244" alt="Landometer"><a class="yolk-brand" href="#market"><span>CityMETER:</span><strong>Yolk</strong></a><p class="brand-line">${tr('ไข่แดงที่ Demand เข้มข้น<br>เริ่มตรงนี้ แล้วมองหาช่องว่างของสาขา','Concentrated demand.<br>Find the yolk, then the supply gap.')}</p><a class="workspace" href="#team"><span class="workspace-mark">${uiIcon('groups')}</span><div><strong>${tr('บางจาก · ทีมขยายสาขา','Bangchak · Expansion team')}</strong><small>Enterprise · 10 ${tr('สมาชิก','members')}</small></div></a><nav aria-label="${tr('เมนูหลัก','Main navigation')}">${navItems.map(([id,th,en])=>`<a class="${Y.route===id?'active':''}" href="#${id}" ${Y.route===id?'aria-current="page"':''}>${uiIcon(navIcon[id])}<span class="nav-label">${tr(th,en)}</span>${id==='supply'?`<span class="nav-count">${Y.pois.filter(x=>!x.archived&&(x.relation==='unverified'||x.status==='pending')).length}</span>`:''}</a>`).join('')}</nav>`;
 $('#header').innerHTML=`<a class="compact-brand" href="#market" aria-label="CityMETER: Yolk — ${tr('หาไข่แดง','Find the yolk')}">Yolk<span>CityMETER · ${tr('หาไข่แดง','Find the yolk')}</span></a><div class="crumb"><span>${tr('บางจาก · ทีมขยายสาขา','Bangchak · Expansion team')}</span><span>/</span><strong>${tabTitle(Y.route)}</strong></div><div class="header-tools"><button class="inbox-button shell-action" data-action="inbox" aria-label="${tr('แจ้งเตือน','Notifications')}${unreadCount()?' · '+unreadCount():''}">${uiIcon('notifications')}<span class="shell-action-label">${tr('เตือน','Inbox')}</span>${unreadCount()?`<span class="count-badge">${unreadCount()}</span>`:''}</button><details class="header-settings" data-header-settings ${settingsOpen?'open':''}><summary class="shell-action">${uiIcon('menu')}<span class="shell-action-label">${tr('เมนู','Menu')}</span></summary><div class="header-menu-panel"><img class="landometer-identity-img header-identity" src="assets/landometer-logo-horizontal-v12-889.png" width="889" height="244" alt="Landometer"><strong class="header-menu-title">${tr('ตั้งค่าการใช้งาน','Your settings')}</strong><p class="header-menu-note">${tr('ต้นแบบ · ข้อมูลจำลอง','Prototype · synthetic data')}</p>${YolkTheme.renderControl(Y.lang)}<div class="header-menu-language"><span>${tr('ภาษา','Language')}</span><button class="language-toggle" data-action="language" aria-label="${tr('Switch to English','เปลี่ยนเป็นภาษาไทย')}">${Y.lang==='th'?'English':'ไทย'}</button></div><label class="person-selector"><span>${tr('ทดลองใช้ในบทบาท','Try a team role')}</span><select id="actor-select">${PEOPLE.map(p=>`<option value="${p.id}" ${p.id===Y.actor?'selected':''}>${person(p.id)} · ${p.role}</option>`).join('')}</select></label><a class="header-team-link" href="#team">${uiIcon('groups')}${tr('ทีมและสิทธิ์','Team & roles')}</a></div></details></div>`;
 const mobileLabels={market:['ไข่แดง','Yolk'],targets:['เล็งไว้','Saved'],supply:['สาขา','Branches'],criteria:['เกณฑ์','Criteria'],feed:['ประวัติ','Activity']};
 $('#mobile-nav').innerHTML=navItems.map(([id])=>`<a class="${Y.route===id?'active':''}" href="#${id}" ${Y.route===id?'aria-current="page"':''}>${uiIcon(navIcon[id])}<span>${tr(...mobileLabels[id])}</span></a>`).join('');
 document.title=tabTitle(Y.route)+' · CityMETER: Yolk';
 if(languageFocused)$('#header').querySelector?.('[data-action="language"]')?.focus?.();
}
function scoreText(a){return YolkDecisions.rankText(a)}

function placeRow(a,index){let saved=!!Y.targets[a.id]&&!Y.targets[a.id].archived;return `<article class="place-row ${Y.selected===a.id?'selected':''}" data-place="${a.id}"><div class="row-top"><span class="rank">${String(index+1).padStart(2,'0')}</span><div class="location-main"><button class="location-title" data-action="place" data-id="${a.id}">${escapeHTML(areaName(a.id))}</button><small>${escapeHTML(provinceName(a.province))} · ${tr(a.geoType==='khwaeng'?'แขวง':'อปท.',a.geoType==='khwaeng'?'Khwaeng':'Local authority')}</small></div><div class="score">${scoreText(a)}<small>${YolkDecisions.rankLabel()}</small></div></div><div class="row-tags">${yolkBadge(a)}<span class="row-tier">${YolkDecisions.tierText(a)}</span><span class="tag ${a.pattern&&a.demand?'high':'wait'}">${window.YolkIcons?.patternIcon(a.pattern)||''}${a.pattern||tr('รอข้อมูล','Needs evidence')} ${a.stars?'★'.repeat(a.stars):''}</span><span class="small">${tr('เรา','Own')} ${a.supply.own} · ${tr('คู่แข่ง','Rivals')} ${a.supply.competitor}${a.supply.unverified?` · ${tr('รอตรวจ','Pending')} ${a.supply.unverified}`:''}</span></div><div class="place-row-footer"><button class="btn view-details" data-action="place" data-id="${a.id}">${uiIcon('location_on')}${tr('ดูรายละเอียด','View details')}</button><button class="btn ${saved?'saved':'soft'} small-button" data-action="target" data-id="${a.id}" ${!canEdit()?'disabled':''}>${uiIcon(saved?'bookmark_added':'bookmark_add')}${saved?tr('เล็งไว้แล้ว','Saved'):tr('เล็งทำเลนี้','Shortlist')}</button></div></article>`}
function yolkBadge(a){return a.demand===true?`<span class="yolk-badge">${window.YolkIcons?.yolkIcon()||''}${tr('Yolk · ไข่แดง','Yolk · High demand')}</span>`:`<span class="demand-status">${a.demand===null?tr('Demand ยังไม่ชัด','Demand unresolved'):tr('Demand ยังไม่สูง','Demand below threshold')}</span>`}
function mapStats(rows){return P.map(p=>{let areas=rows.filter(a=>a.province===p.code),eligible=areas.filter(a=>a.eligible),yolks=areas.filter(a=>a.demand===true),visibleYolks=yolks.filter(a=>Y.mapScope==='all'||a.eligible);return {...p,areas,eligible,yolks,visibleYolks,best:visibleYolks.length?Math.max(...visibleYolks.map(a=>a.score)):null,missing:visibleYolks.length===0&&areas.some(a=>a.demand===null)}})}
function provinceSummary(s){return `${provinceName(s.code)} · ${num(s.yolks.length)} ${tr('ไข่แดงทั้งหมด','Yolks in total')} · ${num(s.visibleYolks.length)} ${tr('ไข่แดงในมุมมองนี้','Yolks in this view')} · ${num(s.eligible.length)} ${tr('ทำเลผ่านเกณฑ์ทีม','locations match team criteria')}${s.missing?' · '+tr('ข้อมูล Demand บางส่วนยังไม่ครบ','Some Demand evidence unresolved'):''}`}
function choropleth(stats){return `<svg id="thai-map" viewBox="0 0 640 900" aria-label="${tr('แผนที่ 77 จังหวัด แสดงไข่แดงที่ Demand สูง','77-province map of high-demand Yolk locations')}" role="group"><defs><pattern id="unknown-hatch" width="7" height="7" patternUnits="userSpaceOnUse"><rect width="7" height="7" fill="var(--yl-no-data)"/><path d="M-1 1 1-1M0 7 7 0M6 8 8 6" stroke="var(--yl-border-strong)" stroke-width="1"/></pattern></defs>${stats.map(s=>`<path class="province ${Y.province===s.code?'selected':''}" d="${s.path}" fill-rule="evenodd" fill="${s.missing?'url(#unknown-hatch)':s.best===null?'var(--no-result)':`var(--yl-yolk-map-${s.best>=99?3:s.best>=95?2:1})`}" data-action="province" data-code="${s.code}" tabindex="0" role="button" aria-label="${escapeHTML(provinceSummary(s))}"><title>${escapeHTML(provinceSummary(s))}</title></path>`).join('')}</svg>`}
function market(){
 let all=evaluate(),stats=mapStats(all),passing=all.filter(a=>a.eligible),selected=Y.province?stats.find(p=>p.code===Y.province):null;
 let q=Y.listQuery.toLowerCase(),list=(selected?selected.areas:passing).filter(a=>(areaName(a.id)+' '+provinceName(a.province)).toLowerCase().includes(q));
 Y.marketPage=Math.max(0,Math.min(Y.marketPage,Math.ceil(list.length/12)-1));let offset=Y.marketPage*12;
 return `<div class="page-head"><div><h1><span class="yolk-title">${window.YolkIcons?.yolkIcon()||''}${tr('หา Yolk หาไข่แดง','Find your Yolk.')}</span> ${tr('เพื่อขยายตลาด','Grow your market.')}</h1><p>${tr('ไข่แดง คือทำเลที่ Demand เข้มข้น แล้วค่อยดูช่องว่างของสาขาเพื่อเลือกที่ไปต่อ','A Yolk is a place with concentrated demand. Compare branch supply to decide where to explore next.')}</p></div><a class="btn primary" href="#criteria">${uiIcon('tune')}${tr('ปรับเกณฑ์ของทีม','Adjust team criteria')}</a></div>
 <div class="market-status"><span>${tr(PRESETS.bangchak.th,PRESETS.bangchak.en)} · v${Y.criteria.version}</span><span><strong>${num(passing.length)}</strong> / ${num(all.length)} ${tr('ทำเลผ่านเกณฑ์','locations qualify')}</span><span>${tr('เทียบทั้งประเทศ · กทม. ใช้แขวง / ต่างจังหวัดใช้ อปท.','One nationwide benchmark · Bangkok khwaeng / upcountry local authorities')}</span></div>
 <div class="national-layout"><section class="national-map" aria-labelledby="map-heading"><div class="map-heading"><div><h2 id="map-heading">${window.YolkIcons?.yolkIcon()||''}${tr('ไข่แดงอยู่ที่ไหน','Where are the Yolks?')}</h2><p>${tr('เลือกจังหวัด แล้วเจาะดูทำเล','Select a province to explore all its locations')}</p></div>${Y.province?`<button class="btn small-button" data-action="clear-province">${uiIcon('map')}${tr('ทั้งประเทศ','Nationwide')}</button>`:'<span class="tag">77 '+tr('จังหวัด','provinces')+'</span>'}</div>
 <fieldset class="map-scope"><legend>${tr('แสดงไข่แดง','Show Yolks')}</legend>${[['preferred','ตรงเกณฑ์ทีม','Matching team criteria'],['all','ไข่แดงทั้งหมด','All high-demand locations']].map(([id,th,en])=>`<label><input type="radio" name="map-scope" value="${id}" ${((Y.mapScope||'preferred')===id)?'checked':''}>${tr(th,en)}</label>`).join('')}</fieldset><p class="map-view-note">${Y.mapScope==='all'?tr('ดู Demand โดยยังไม่กรอง Tier และ Supply · รายการด้านขวายังใช้เกณฑ์ทีม','Demand view before Tier and Supply filters. The ranked list still follows team criteria.'):tr('แสดงไข่แดงที่ผ่านทั้ง Tier และรูปแบบทำเลที่ทีมเลือก','Yolks that pass the selected Tier and preferred location types.')}</p>
 <div class="national-map-body">${choropleth(stats)}<div class="map-explainer"><strong>${window.YolkIcons?.yolkIcon()||''}${tr('สีทอง = พบไข่แดง','Gold = Yolk found')}</strong><p>${tr('แต่ละจังหวัดใช้สัญญาณ Demand ที่เด่นที่สุดจากไข่แดงในมุมมองนี้ ไม่ใช่คะแนนทั้งจังหวัดหรือจำนวนลูกค้า','Each province shows the strongest demand-signal percentile among its visible Yolks, not a province score or customer count.')}</p><span class="tag">${tr('ข้อมูลจำลอง · เทียบทั่วประเทศ','Synthetic data · National benchmark')}</span></div></div>
 <div class="legend-block"><div class="yolk-map-legend">${[[1,'ผ่านเกณฑ์ Demand','Meets Demand threshold','< P95'],[2,'กลุ่มบน 5%','Top 5%','P95–<99'],[3,'กลุ่มบน 1%','Top 1%','P99–100']].map(([level,th,en,p])=>`<span><i style="background:var(--yl-yolk-map-${level})"></i><strong>${tr(th,en)}</strong><small>${p}</small></span>`).join('')}</div><div class="secondary-legend"><span><i class="no-result-swatch"></i>${tr('ไม่มีไข่แดงในมุมมองนี้','No Yolk in this view')}</span><span><i class="missing-swatch"></i>${tr('ไม่มีไข่แดงในมุมมองนี้ และ Demand บางส่วนยังไม่ครบ','No Yolk in this view; some Demand unresolved')}</span></div><p class="source-credit">Boundaries © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> · geoBoundaries · ODbL · 2017</p></div></section>
 <aside class="national-ranking"><div class="ranking-head"><h2 id="province-results" tabindex="-1">${selected?escapeHTML(provinceName(selected.code)):tr('ทำเลที่ควรดูต่อ','Locations to explore')}</h2>${selected?`<p class="province-counts">${num(selected.yolks.length)} ${tr('ไข่แดงทั้งหมด','Yolks in total')} · ${num(selected.visibleYolks.length)} ${tr('ไข่แดงในมุมมองนี้','Yolks in this view')} · ${num(selected.eligible.length)} ${tr('ทำเลผ่านเกณฑ์ทีม','locations match team criteria')}</p>`:''}<p>${Y.criteria.rankingMode==='weighted'?tr('ทำเลที่ผ่านเกณฑ์ เรียงตามน้ำหนักที่ทีมเลือก','Eligible locations, ordered by team weights'):tr('เรียงตามวิธีเดิม: ผ่านเกณฑ์ → ดาว → Tier','Previous order: eligibility → stars → tier')}</p></div><label class="search">${uiIcon('search')}${tr('ค้นหา','Search')}<input id="location-search" value="${escapeHTML(Y.listQuery)}" aria-label="${tr('ค้นหาทำเลหรือจังหวัด','Search location or province')}" placeholder="${tr('ทำเล / จังหวัด','Location / province')}"></label><div class="ranking-list">${list.length?list.slice(offset,offset+12).map((a,i)=>placeRow(a,offset+i)).join(''):`<div class="empty"><h3>${tr('ยังไม่มีทำเลตรงเกณฑ์','No matching locations')}</h3><a href="#criteria" class="btn">${tr('ดูเกณฑ์','View criteria')}</a></div>`}</div><div class="pagination"><button class="btn small-button" data-action="market-prev" ${Y.marketPage===0?'disabled':''}>${tr('ก่อนหน้า','Previous')}</button><span>${num(list.length)} ${tr('ทำเล','locations')} · ${Y.marketPage+1}/${Math.max(1,Math.ceil(list.length/12))}</span><button class="btn small-button" data-action="market-next" ${offset+12>=list.length?'disabled':''}>${tr('ถัดไป','Next')}</button></div><p class="footline">${tr('ข้อมูลจำลองสำหรับทดลองระบบ ไม่ใช่ผลวิเคราะห์ตลาดจริง','Demand and Supply here are synthetic demonstration values, not for investment decisions.')}</p></aside></div>`
}

function changeView(e){return e.changes.map(c=>`<div class="change-line"><span>${fieldNames[c.field]?tr(...fieldNames[c.field]):escapeHTML(c.field)}</span><div><del>${escapeHTML(displayValue(c.before,c.field))}</del><span class="change-arrow">→</span><strong>${escapeHTML(displayValue(c.after,c.field))}</strong></div></div>`).join('')}
function feed(events,{limit=6,links=true}={}){if(!events.length)return `<div class="feed-empty">${tr('ยังไม่มีการเปลี่ยนแปลงในหน้านี้','No changes in this context yet')}</div>`;return `<ol class="context-feed">${events.slice(0,limit).map(e=>`<li class="feed-item ${e.recipients.includes(Y.actor)&&!(Y.read[Y.actor]||[]).includes(e.id)?'unread':''}"><span class="feed-avatar">${escapeHTML(person(e.actor).slice(0,1))}</span><div class="feed-body"><div class="feed-byline"><strong>${escapeHTML(person(e.actor))}</strong><span>${eventTitle(e)}</span>${e.recipients.includes(Y.actor)&&!(Y.read[Y.actor]||[]).includes(e.id)?`<span class="unread-label">${tr('ใหม่','New')}</span>`:''}<time datetime="${e.at}">${eventTime(e.at)}</time></div>${e.meta.sample?`<small>${tr('ตัวอย่างเหตุการณ์เริ่มต้น','Seed example event')}</small>`:''}${e.entity==='place'?`<p class="feed-context">${escapeHTML(areaName(e.entity_id))} · ${escapeHTML(provinceName(AREAS.find(a=>a.id===e.entity_id)?.province))}</p>`:e.entity==='supply'?`<p class="feed-context">${escapeHTML(branchName(Y.pois.find(p=>p.id===e.entity_id)||{name:e.entity_id}))}</p>`:''}${changeView(e)}<div class="feed-receipt"><span>${tr('แจ้งสมาชิกอื่น','Notified other members')} ${e.recipients.length} ${tr('คน','people')} · ${tr('ในต้นแบบ','in this demo')}</span>${links?`<button class="quiet-link" data-action="event-context" data-id="${e.id}">${tr('เปิดบริบท','Open context')} →</button>`:''}</div></div></li>`).join('')}</ol>`}
function numberControl(key,th,en,min=1,max=100){return `<div class="field"><label for="c-${key}">${tr(th,en)}</label><input id="c-${key}" data-criterion="${key}" type="number" min="${min}" max="${max}" value="${draft[key]}"></div>`}
function metricList(ids,p=95){return `<ul class="metric-list">${ids.map(id=>{let m=METRIC_INDEX[id];return `<li><span>${tr(m.th,m.en)}<small>${tr(m.unitTh,m.unitEn)}</small></span><span class="metric-cutoff" data-cutoff-id="${id}">P${p} ≥ ${num(cutoff(id,p),2)}</span></li>`}).join('')}</ul>`}
function metricReason(m){let r={crosswalk:['รอเชื่อมข้อมูลกับขอบเขตพื้นที่ให้ครบ','Area crosswalk and coverage pending'],size:['รอยืนยันนิยามขนาดใหญ่และเชื่อมพื้นที่','Size definition and area crosswalk pending'],health:['รอยืนยันแหล่งข้อมูลและนิยามขนาด','Source and size definition pending'],traffic:['รอยืนยันช่วงเวลาวัดและขอบเขตถนน','Measurement period and road coverage pending']};return m.ready?tr('มีข้อมูลให้ทดลอง · ยังไม่เปิดใช้','Available to preview · off by default'):tr(...r[m.reason])}
function demandControls(){return `<section class="section demand-section"><div class="block-title"><h2>1. Demand</h2><span class="tag high">${tr('เกณฑ์บางจาก','Bangchak criteria')}</span></div><p class="rule-caption">${tr('Tier แสดงความเข้มของสัญญาณ แล้วเลือก Tier ที่รับไว้ในหมวดรูปแบบทำเลที่สนใจ','Tiers describe signal strength. Select the tiers to include under Preferred location types.')}</p><p class="lead">${tr('ผ่านกลุ่มสัญญาณที่เปิดใช้อย่างน้อยหนึ่งกลุ่ม = Demand สูง','High demand requires at least one enabled signal group to qualify.')}</p>
 <div class="signal-group"><label class="signal-toggle"><input type="checkbox" data-toggle="buildingEnabled" ${draft.buildingEnabled?'checked':''}><strong>${tr('สัญญาณจากอาคาร · 3 ตัวชี้วัด','Building signals · 3 metrics')}</strong></label>${metricList(BUILDING_IDS,draft.buildingP2)}<div class="inline-fields">${numberControl('buildingP1','Tier 1: ทั้ง 3 ข้อ ≥ P','Tier 1: all 3 at or above P')}${numberControl('buildingP2','Tier 2/3: เกณฑ์ ≥ P','Tier 2/3: threshold P')}</div><p class="rule-caption">${tr('Tier 2: ผ่าน 3 ข้อ · Tier 3: ผ่านอย่างน้อย 1 ข้อ · ใช้ Tier ที่ดีที่สุด','Tier 2: all 3 pass · Tier 3: at least 1 passes. Assign the best qualifying tier.')}</p></div>
 <div class="signal-group"><label class="signal-toggle"><input type="checkbox" data-toggle="activityEnabled" ${draft.activityEnabled?'checked':''}><strong>${tr('สัญญาณจากกิจกรรม · 6 ตัวชี้วัด','Activity signals · 6 metrics')}</strong></label>${metricList(ACTIVITY_IDS,draft.activityP)}${numberControl('activityP','กิจกรรมแต่ละข้อผ่านเมื่อ ≥ P','Each activity metric passes at or above P')}<div class="tier-inputs">${[1,2,3].map(n=>numberControl('activityT'+n,'Tier '+n+': อย่างน้อย (ข้อ)','Tier '+n+': at least (hits)',1,6)).join('')}</div></div>
 <details class="metric-catalog"><summary>${tr('ปัจจัยเพิ่มเติมสำหรับธุรกิจประเภทอื่น','Additional factors for other industries')}</summary><p>${tr('เลือกปัจจัยที่มีข้อมูลได้ทันที ปัจจัยที่ยังไม่มีข้อมูลจะไม่เข้าคำนวณ','Ready signals can be enabled. Unconnected factors stay visible without affecting results.')}</p>${METRICS.filter(m=>!CORE_IDS.includes(m.id)).map(m=>`<label class="catalog-row ${m.ready?'':'unavailable'}"><input type="checkbox" data-extra="${m.id}" ${draft.extraMetrics.includes(m.id)?'checked':''} ${m.ready?'':'disabled'}><span><strong>${tr(m.th,m.en)}</strong><small>${tr(m.unitTh,m.unitEn)} · ${metricReason(m)}</small></span></label>`).join('')}${numberControl('extraP','ปัจจัยเพิ่มเติมผ่านเมื่อ ≥ P','Additional signals pass at or above P')}<p class="footline">${tr('ปัจจัยที่เปิดใช้และผ่านเกณฑ์อย่างน้อย 1 ข้อ นับเป็น Demand สูงด้วย ข้อมูลประชากรระดับพื้นที่อาจเทียบยอดรวมจังหวัดไม่ได้โดยตรง','If enabled, any passing additional signal also indicates high demand. Area population remains a proxy with province-total reconciliation limits.')}</p></details>
<p class="footline">${tr('ใช้ Percentile ฐานทั้งประเทศ · ข้อมูลที่ขาดไม่แทนด้วยศูนย์','Raw values use nationwide percentile cutoffs. Missing values are never zero.')}</p></section>`}


function supplyControls(){return `<section class="section supply-section"><div class="block-title"><h2>2. Supply</h2><span class="tag blue">${tr('ใครให้บริการอยู่แล้ว','Existing branch network')}</span></div><p class="lead">${tr('กำหนดว่าจำนวนสาขาเท่าไรจึงเรียกว่า “มาก” แยกบางจากและคู่แข่ง','Define when supply counts as high, separately for Bangchak and competitors.')}</p><div class="inline-fields"><div class="field"><label for="own-many">${tr('บางจากเริ่ม “มาก” ที่ (สาขา)','Bangchak is high from (branches)')}</label><input id="own-many" data-criterion="ownMany" type="number" min="1" max="100" value="${draft.ownMany}"></div><div class="field"><label for="competitor-many">${tr('คู่แข่งเริ่ม “มาก” ที่ (สาขา)','Competitors are high from (branches)')}</label><input id="competitor-many" data-criterion="competitorMany" type="number" min="1" max="100" value="${draft.competitorMany}"></div></div><p class="footline">${tr('น้อย = ต่ำกว่าเกณฑ์ มาก = ตั้งแต่เกณฑ์ขึ้นไป สาขาที่ไม่ทราบแบรนด์ยังเป็นรายการรอตรวจ','Low is below the threshold; high is at or above it. Unknown brands remain unverified.')}</p><a class="btn" href="#supply">${uiIcon('fact_check')}${tr('ดูสาขาและรายการรอตรวจ','Review branches and unverified records')}</a></section>`}

function impact(){
 const errors=criteriaErrors(draft);
 if(errors.length)return `<h2>${tr('ตรวจเกณฑ์ก่อนดูผล','Check criteria to preview')}</h2><p>${tr('เปิดสัญญาณ Demand อย่างน้อยหนึ่งกลุ่ม เลือกอย่างน้อยหนึ่งรูปแบบ และตรวจค่าตัวเลข น้ำหนักแต่ละชุดต้องไม่เป็นศูนย์ทั้งหมด','Enable a demand group, choose at least one location type, and check numeric values. Each active weight set needs a positive total.')}</p><p class="footline">${tr('Percentile 1–100 · Tier 1 ≥ Tier 2 ≥ Tier 3 ข้อ · น้ำหนัก 0–100','Percentiles 1–100 · Tier hit counts descend from Tier 1 to Tier 3 · weights 0–100')}</p>`;
 const old=evaluate(Y.criteria).filter(a=>a.eligible),next=evaluate(draft).filter(a=>a.eligible),oldIDs=new Set(old.map(a=>a.id)),nextIDs=new Set(next.map(a=>a.id)),oldRanks=new Map(old.map((a,i)=>[a.id,i+1]));
 const added=next.filter(a=>!oldIDs.has(a.id)).length,removed=old.filter(a=>!nextIDs.has(a.id)).length,moved=next.filter((a,i)=>oldRanks.has(a.id)&&oldRanks.get(a.id)!==i+1).length,diff=diffCriteria(Y.criteria,draft);
 return `<h2>${tr('ปรับแล้ว อะไรเปลี่ยน','What changes?')}</h2><p class="lead">${tr('เทียบกับเกณฑ์ทีม','Compared with team criteria')} v${Y.criteria.version}</p><div class="impact-total"><span>${old.length}</span><span>→</span><strong>${next.length}</strong><small>${tr('ทำเลผ่านเกณฑ์','eligible locations')}</small></div><div class="impact-delta"><span>+${added} ${tr('เข้าเกณฑ์','newly qualify')}</span><span>−${removed} ${tr('หลุดเกณฑ์','no longer qualify')}</span></div><p class="impact-rank-note"><strong>${moved}</strong> ${tr('ทำเลเดิมมีอันดับเปลี่ยน','previously eligible locations change rank')}<br>${tr('ปรับน้ำหนักอย่างเดียว จำนวนที่ผ่านจะเท่าเดิม แต่อันดับอาจเปลี่ยน','Weights alone keep the same qualifying set but can change its order.')}</p>${next.slice(0,5).map((a,i)=>`<div class="mini-row"><span class="mini-rank">${i+1}</span><span>${escapeHTML(areaName(a.id))}<small>${escapeHTML(provinceName(a.province))} · ${YolkDecisions.tierText(a)}</small><span class="rank-move">${oldRanks.has(a.id)?tr('อันดับ ','Rank ')+oldRanks.get(a.id)+' → '+(i+1):tr('เข้าใหม่','Newly eligible')}</span></span><span class="num">${YolkDecisions.rankText(a,draft)}</span></div>`).join('')}<p class="footline">${YolkDecisions.rankLabel(draft)} · ${tr('เป็นแบบร่างจนกดใช้กับทีม','Draft until applied to the workspace')}</p><button class="btn primary apply-button" data-action="apply-criteria" ${!canEdit()||!diff.length?'disabled':''}>${uiIcon('save')}${tr('ใช้เกณฑ์นี้กับทีม','Apply to workspace')}</button><p class="scope-note">${tr('บันทึกค่าเดิม–ใหม่ในประวัติ และแจ้งสมาชิกอีก 9 คน','Saves before/after values to the feed and notifies the other 9 members.')}</p>${!canEdit()?`<p class="tag wait">${tr('Viewer ทดลองปรับได้ แต่ใช้กับทีมไม่ได้','Viewers can preview, but cannot apply team changes.')}</p>`:''}`;
}

function geographySummary(){return `<section class="geography-summary" aria-label="${tr('หน่วยพื้นที่วิเคราะห์','Analytical geography')}"><div><span class="eyebrow">${tr('หน่วยวิเคราะห์หลัก','Primary analytical unit')}</span><strong>${tr('กทม. → แขวง · ต่างจังหวัด → อปท.','Bangkok → khwaeng · Elsewhere → local authorities')}</strong><p>${tr('อปท. ใช้หน่วยระดับพื้นที่ที่ตรวจแล้ว รวมรูปแบบพิเศษ โดยไม่รวม อบจ. ที่ทับซ้อน ภาพจังหวัดมีไว้ดูภาพรวม','Use validated local authority areas, including eligible special forms, excluding overlapping PAOs. Provinces provide an overview.')}</p></div><details><summary>${tr('ตัวเลือกพื้นที่ในอนาคต','Future geography options')}</summary><p>${tr('จังหวัด · อำเภอ/เขต · ตำบล/แขวง · อปท. · Custom location','Province · District · Subdistrict · Local authority · Custom location')}</p><small>${tr('เมื่อเปลี่ยนหน่วยพื้นที่ ต้องคำนวณตัววัดและ Percentile ใหม่ การกรองจังหวัดไม่เปลี่ยนฐานเทียบ','Changing the unit recomputes raw metrics and the nationwide percentile benchmark. Filtering a province does not.')}</small></details></section>`}

function mobileImpact(){let valid=criteriaErrors(draft).length===0,old=evaluate(Y.criteria).filter(a=>a.eligible).length,next=valid?evaluate(draft).filter(a=>a.eligible).length:'—';return `<div id="mobile-impact" class="mobile-impact"><div aria-live="polite"><span>${tr('ทำเลผ่านเกณฑ์ · ทดลอง','Eligible locations · draft')}</span><strong>${old} → ${next}</strong></div><button class="btn primary" data-action="jump-preview">${uiIcon('tune')}${tr('ดูผลเปลี่ยนแปลง','Review impact')}</button></div>`}
function criteria(){return `<div class="page-head"><div><h1>${tr('เกณฑ์เดียวกัน เห็นโอกาสร่วมกัน','Shared criteria. A shared view.')}</h1><p>${tr('ปรับ Demand และ Supply แล้วดูผลก่อนใช้กับทีม','Adjust Demand and Supply separately. Preview before applying to the team.')}</p></div><span class="version-tag">${tr('เกณฑ์ทีม','Team criteria')} v${Y.criteria.version}</span></div>${geographySummary()}<ol class="criteria-flow"><li><strong>1. Demand</strong>${tr('วัดความต้องการ','Measure demand')}</li><li><strong>2. Supply</strong>${tr('ดูสาขาที่มีอยู่','Define supply levels')}</li><li><strong>3. ${tr('รูปแบบที่สนใจ','Preferred types')}</strong>${tr('เลือกกลุ่มและ Tier','Select types and tiers')}</li><li><strong>4. ${tr('น้ำหนัก','Weights')}</strong>${tr('เรียงทำเลที่ผ่าน','Rank qualifying locations')}</li></ol><div class="criteria-grid"><div class="criteria-form">${demandControls()}${supplyControls()}${YolkDecisions.preferred()}${YolkDecisions.ranking()}<div class="criteria-footer"><button class="btn" data-action="reset-draft">${uiIcon('history')}${tr('คืนค่าเกณฑ์ทีม','Reset to team settings')}</button><span class="small">${tr('แบบร่างยังไม่มีผลกับสมาชิกอื่น','Draft changes do not affect other members')}</span></div></div><aside class="criteria-impact"><section class="section preview-box" id="impact-preview" tabindex="-1">${impact()}</section><div class="data-disclosure"><span>${tr('ข้อมูลที่ขาดแยกไว้ตรวจเพิ่ม ฐาน Percentile ใช้ทั้งประเทศเสมอ','Missing is not zero. Incomplete evidence stays in review. Province filters do not change the percentile benchmark.')}</span></div></aside></div><section class="section full-feed"><div class="block-title"><h2>${tr('ใครปรับเกณฑ์ อะไร เมื่อไร','Who changed what, and when')}</h2><span class="tag">${tr('ทั้ง workspace','Workspace-wide')}</span></div>${feed(Y.events.filter(e=>e.entity==='criteria'),{links:false})}</section>${mobileImpact()}`}




function place(){let a=evaluate().find(x=>x.id===Y.selected);if(!a)return `<div class="empty">${tr('ไม่พบทำเล','Location not found')}</div>`;let t=Y.targets[a.id]?.archived?null:Y.targets[a.id],events=Y.events.filter(e=>(e.entity==='place'&&e.entity_id===a.id)||(e.entity==='supply'&&(e.meta.area===a.id||e.meta.previousArea===a.id)));return `<a class="back" href="#market">${uiIcon('arrow_back')}${tr('กลับไปภาพรวมประเทศ','Back to market map')}</a><div class="page-head"><div><p class="eyebrow">${escapeHTML(provinceName(a.province))} · ${tr(a.geoType==='khwaeng'?'แขวง':'อปท.',a.geoType==='khwaeng'?'Khwaeng':'Local authority')}</p><h1>${escapeHTML(areaName(a.id))}</h1><p>${tr('ความต้องการในพื้นที่ และช่องว่างของสาขาบางจาก','A local market view through Bangchak’s network.')}</p></div><button class="btn" data-action="share">${uiIcon('share')}${tr('แชร์ทำเล','Share location')}</button></div><div class="location-verdict">${yolkBadge(a)}<span class="tag ${a.eligible?'high':'wait'}">${a.eligible?tr('ผ่านเกณฑ์ทีม','Meets team criteria'):tr('ยังไม่เข้าเกณฑ์ทีม','Outside team shortlist criteria')}</span><strong>${window.YolkIcons?.patternIcon(a.pattern)||''}${a.pattern||tr('รอหลักฐานเพื่อจำแนก','Classification unresolved')} ${a.stars?'★'.repeat(a.stars):''}</strong><a href="#criteria">${tr('เกณฑ์ทีม','Team criteria')} v${Y.criteria.version}</a></div>${YolkDecisions.detail(a)}${YolkLocationMap.render(a,Y.pois,Y.lang)}${renderMarketLandscape(a)}<div class="location-sources"><span class="tag">${tr('ทำเลจำลอง','Synthetic location')}</span><button class="quiet-link" data-action="place-branches">${uiIcon('local_gas_station')}${tr('ดูสาขาในทำเลนี้','View available branch records')} →</button></div><div class="detail-grid"><div><section class="section"><h2>${tr('งานของทำเลนี้','Location work')}</h2>${t?`<form id="target-form"><div class="inline-fields"><div class="field"><label for="target-owner">${tr('ผู้รับผิดชอบ','Owner')}</label><select id="target-owner" name="owner" ${!canEdit()?'disabled':''}>${PEOPLE.filter(p=>p.role!=='viewer').map(p=>`<option value="${p.id}" ${t.owner===p.id?'selected':''}>${person(p.id)}</option>`).join('')}</select></div><div class="field"><label for="target-status">${tr('สถานะ','Status')}</label><select id="target-status" name="status" ${!canEdit()?'disabled':''}>${['survey','study','hold','rejected'].map(v=>`<option value="${v}" ${t.status===v?'selected':''}>${tr(...valLabels[v])}</option>`).join('')}</select></div></div><div class="field"><label for="target-note">${tr('บันทึกของทีม','Team note')}</label><textarea id="target-note" name="note" rows="3" maxlength="1000" ${!canEdit()?'disabled':''}>${escapeHTML(t.note)}</textarea></div><div class="form-actions"><button class="btn primary" type="submit" ${!canEdit()?'disabled':''}>${uiIcon('save')}${tr('บันทึกและแจ้งทีม','Save & notify team')}</button><button class="quiet-link" type="button" data-action="target" data-id="${a.id}" ${!canEdit()?'disabled':''}>${uiIcon('delete')}${tr('นำออกจากรายการเล็งไว้','Remove from shortlist')}</button></div></form>`:`<p>${tr('เล็งทำเลนี้ไว้ แล้วมอบหมายงานและบันทึกสิ่งที่พบ','Shortlist this location to assign work and record field findings.')}</p><button class="btn primary" data-action="target" data-id="${a.id}" ${!canEdit()?'disabled':''}>${uiIcon('bookmark_add')}${tr('เล็งทำเลนี้','Shortlist location')}</button>`}</section></div><aside><section class="section full-feed"><div class="block-title"><h2>${tr('ประวัติทำเล','Location feed')}</h2><span class="tag">${events.length}</span></div>${feed(events,{limit:12,links:false})}</section><p class="data-disclosure">${tr('ทำเลจำลอง · บันทึกและแจ้งเตือนเฉพาะในเครื่อง · ศึกษารายแปลงในขั้นถัดไป','This location uses synthetic data. Edits and notifications are local to this prototype. Parcel assessment is a later step.')}</p></aside></div>`}

function targets(){let list=evaluate().filter(a=>Y.targets[a.id]&&!Y.targets[a.id].archived);return `<div class="page-head"><div><h1>${tr('จากทำเลที่น่าสนใจ สู่แผนของทีม','From promising places to a team plan.')}</h1><p>${tr('ผู้รับผิดชอบ สถานะ และบันทึก ใช้ร่วมกันทั้งทีม','Owners, status and notes are shared across the workspace.')}</p></div><a class="btn primary" href="#market">${tr('ค้นหาทำเลเพิ่ม','Explore more locations')}</a></div><div class="shortlist-grid">${list.map((a,i)=>`<div>${placeRow(a,i)}<div class="target-meta"><span>${person(Y.targets[a.id].owner)}</span><span>${tr(...valLabels[Y.targets[a.id].status])}</span></div></div>`).join('')||`<div class="empty">${tr('ยังไม่มีทำเลที่เล็งไว้ ลองเริ่มจากภาพรวมประเทศ','No shortlisted locations yet. Start with the market map.')}</div>`}</div><section class="section full-feed"><h2>${tr('ความเคลื่อนไหวของทำเล','Location activity')}</h2>${feed(Y.events.filter(e=>e.entity==='place'))}</section>`}
function activityPage(inbox=false){let events=inbox?Y.events.filter(e=>e.recipients.includes(Y.actor)):Y.events;return `<div class="page-head"><div><h1>${inbox?tr('มีอะไรเปลี่ยนไปบ้าง','What’s changed?'):tr('ทีมกำลังขยับไปทางไหน','Keep up with the team.')}</h1><p>${inbox?tr('การเปลี่ยนแปลงที่เพื่อนร่วมทีมแจ้งถึงคุณ','Changes your teammates shared with you.'):tr('ดูว่าใครเปลี่ยนอะไร เมื่อไร และค่าก่อน–หลัง','Every saved change has an actor, time and before/after values.')}</p></div>${inbox?`<button class="btn" data-action="read-all">${tr('อ่านทั้งหมดแล้ว','Mark all as read')}</button>`:''}</div>${inbox?`<div class="inbox-summary"><strong>${unreadCount()}</strong><span>${tr('ยังไม่ได้อ่าน','unread')} · ${person(Y.actor)}</span><small>${tr('สลับผู้ใช้ตัวอย่างด้านบนเพื่อดูการแจ้งเตือนของเพื่อนร่วมทีม','Switch demo users above to view a teammate’s inbox')}</small></div>`:`<div class="team-strip"><strong>${tr('บางจาก · ทีมขยายสาขา','Bangchak · Expansion team')}</strong><span>1 Admin · 3 Editors · 6 Viewers</span><span>${tr('ทุกคนเห็นข้อมูลชุดเดียวกัน','One shared workspace')}</span></div>`}${inbox?'':renderLeaderboard()}<section class="section full-feed feed-wide">${feed(events,{limit:50})}</section><p class="footline">${tr('ต้นแบบบันทึกในเครื่อง · Email / LINE เป็นตัวอย่าง ยังไม่ส่งจริง','Notifications are local in this prototype · Email / LINE show share previews; nothing is sent.')}</p>`}
function showShare(){let a=AREAS.find(a=>a.id===Y.selected);$('#share-dialog').innerHTML=`<h2>${tr('แชร์บริบทให้ทีม','Share the context')}</h2><p>${tr('ผู้รับที่มีสิทธิ์เปิดทำเลและเกณฑ์เวอร์ชันนี้ได้','Authorized recipients can open this location with this criteria version.')}</p><div class="share-preview"><strong>CityMETER: Yolk</strong><p>${escapeHTML(provinceName(a.province))} · ${escapeHTML(areaName(a.id))}</p><span>${tr('เกณฑ์ทีม','Team criteria')} v${Y.criteria.version}</span></div><div class="share-actions"><button class="btn" data-action="preview-email">Email</button><button class="btn" data-action="preview-line">LINE</button><button class="btn primary" data-action="close-share">${uiIcon('close')}${tr('ปิด','Close')}</button></div><p class="footline">${tr('ตัวอย่างข้อความแชร์เท่านั้น ยังไม่ส่งออกนอกต้นแบบ','Message preview only. No external delivery in this prototype.')}</p><p id="channel-preview" role="status"></p>`;$('#share-dialog').showModal()}

function teamPage(){return `<div class="page-head"><div><h1>${tr('สิบคน ทำงานบนข้อมูลเดียวกัน','Ten people. One shared workspace.')}</h1><p>${tr('Admin 1 คน · Editors 3 คน · Viewers 6 คน','1 Admin · 3 Editors · 6 Viewers')}</p></div><span class="tag">Enterprise · 10 / 10</span></div><div class="detail-grid"><section class="section"><h2>${tr('สมาชิกตัวอย่าง','Demo members')}</h2>${PEOPLE.map(p=>`<div class="team-seat"><span>${person(p.id)} ${p.id===Y.actor?'· '+tr('คุณ','You'):''}</span><span>${p.role}</span></div>`).join('')}</section><aside><section class="section"><h2>${tr('ใครทำอะไรได้','Who can do what')}</h2><p><strong>Admin</strong><br>${tr('กำหนดสิทธิ์และนโยบายข้อมูล พร้อมแก้ไขงานของทีม','Manages members and data policy, and edits shared work.')}</p><p><strong>Editors</strong><br>${tr('บันทึกสาขา ทำเล และใช้เกณฑ์กับ workspace','Edit branches and locations, and apply shared criteria.')}</p><p><strong>Viewers</strong><br>${tr('อ่าน ทดลองเกณฑ์ และติดตามความเคลื่อนไหว','Read, preview criteria, and follow team activity.')}</p><p class="data-disclosure">${tr('สลับผู้ใช้ด้านบนเพื่อทดลองสิทธิ์ ยังไม่มีบัญชีหรือคำเชิญจริง','Switch the demo user above to try roles. This prototype has no real authentication or invitations.')}</p></section></aside></div>`}

let renderedRoute='';
function render(){let route=(location.hash.slice(1).split('/')[0]||'market');if(!['market','targets','supply','criteria','feed','place','poi','inbox','team'].includes(route))route='market';if(route==='criteria'&&renderedRoute!=='criteria'){draft=structuredClone(Y.criteria);draftBase=Y.criteria.version}if(route==='place'){let id=location.hash.split('/')[1];if(AREAS.some(a=>a.id===id))Y.selected=id}YolkLocationMap.destroy();Y.route=route;header();$('.skip').textContent=tr('ข้ามไปเนื้อหา','Skip to content');$('#mobile-nav').setAttribute('aria-label',tr('เมนูหลัก','Primary navigation'));$('#content').innerHTML=({market,targets,supply,criteria,feed:()=>activityPage(),inbox:()=>activityPage(true),place,poi:poiEditor,team:teamPage}[route])();if(route==='supply'){let heads=[...document.querySelectorAll('.supply-table th')].map(el=>el.textContent);document.querySelectorAll('.supply-table tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.setAttribute('data-label',heads[i])))}if(route==='place'){let a=evaluate().find(a=>a.id===Y.selected);if(a)YolkLocationMap.mount(a,Y.pois,Y.lang)}if(route==='poi')YolkBranchPhotos.bind(document,{lang:Y.lang,editable:canEdit(),canEdit});if(route==='criteria')YolkDecisions.sync();renderedRoute=route}
function updateImpact(){ $('#impact-preview').innerHTML=impact();if($('#mobile-impact'))$('#mobile-impact').outerHTML=mobileImpact();YolkDecisions.sync();document.querySelectorAll('[data-cutoff-id]').forEach(el=>{let id=el.dataset.cutoffId,p=BUILDING_IDS.includes(id)?draft.buildingP2:draft.activityP;el.textContent='P'+p+' ≥ '+num(cutoff(id,p),2)}) }
function refreshDecisionSection(id){let el=$('#'+id);if(el)el.outerHTML=id==='preferred-types'?YolkDecisions.preferred():YolkDecisions.ranking();YolkDecisions.sync()}


const committed=()=>notify(tr('บันทึกแล้ว · แจ้งสมาชิกอื่น 9 คนในต้นแบบ','Saved · notified the other 9 demo members'));
document.addEventListener('input',e=>{let el=e.target;if(['location-search','poi-search'].includes(el.id)){let id=el.id,value=el.value;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>{if(!$('#'+id))return;let focused=document.activeElement?.id===id,pos=el.selectionStart;if(id==='location-search'){Y.listQuery=value;Y.marketPage=0}else{Y.poiQuery=value;Y.page=0}render();if(focused){let input=$('#'+id);input.focus();input.setSelectionRange(pos,pos)}},250)}if(el.dataset.criterion){draft[el.dataset.criterion]=el.value===''?NaN:+el.value;updateImpact();if(['ownMany','competitorMany'].includes(el.dataset.criterion))refreshDecisionSection('preferred-types')}if(el.dataset.weightScope){draft[el.dataset.weightScope][el.dataset.weightKey]=el.value===''?NaN:+el.value;updateImpact()}});
document.addEventListener('change',e=>{let el=e.target;if(el.name==='map-scope'){Y.mapScope=el.value==='all'?'all':'preferred';render();document.querySelector('input[name="map-scope"]:checked')?.focus();return}if(el.id==='actor-select'){Y.actor=el.value;save();render();$('#actor-select').focus()}if(el.dataset.pattern){draft.patterns=patternNames.filter(n=>n===el.dataset.pattern?el.checked:draft.patterns.includes(n));el.closest('.preferred-card')?.classList.toggle('is-selected',el.checked);updateImpact()}if(el.dataset.toggle){draft[el.dataset.toggle]=el.checked;refreshDecisionSection('ranking-weights');updateImpact()}if(el.dataset.extra){draft.extraMetrics=METRICS.filter(m=>m.ready&&!CORE_IDS.includes(m.id)&&(m.id===el.dataset.extra?el.checked:draft.extraMetrics.includes(m.id))).map(m=>m.id);refreshDecisionSection('ranking-weights');updateImpact()}if(el.id==='demand-mode'){draft.demandMode=el.value;refreshDecisionSection('preferred-types');$('#demand-mode').focus();updateImpact()}if(el.id==='max-demand-tier'){draft.maxDemandTier=+el.value;updateImpact()}if(el.id==='ranking-mode'){draft.rankingMode=el.value;refreshDecisionSection('ranking-weights');$('#ranking-mode').focus();updateImpact()}if(el.id==='brand-filter'){Y.brandFilter=el.value;Y.page=0;render()}if(el.id==='leader-period'||el.id==='leader-category'){Y[el.id==='leader-period'?'leaderPeriod':'leaderCategory']=el.value;render();$('#'+el.id).focus()}if(el.id==='branch-province')$('#branch-area').innerHTML=areaOptions(el.value,'')});
document.addEventListener('keydown',e=>{if(e.target.matches('svg [data-action="province"]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let action=b.dataset.action,id=b.dataset.id;switch(action){case 'language':{let f=$('#poi-form')||$('#target-form'),v=f?Object.fromEntries(new FormData(f)):null,formID=f?.id,provinceValue=$('#branch-province')?.value;Y.lang=Y.lang==='th'?'en':'th';save();render();if(v){let next=$('#'+formID);if(formID==='poi-form'&&provinceValue){$('#branch-province').value=provinceValue;$('#branch-area').innerHTML=areaOptions(provinceValue,v.area)}for(let [k,x] of Object.entries(v))if(next?.elements[k])next.elements[k].value=x}$('.language-toggle').focus();break;}case 'inbox':location.hash='inbox';break;case 'market-prev':Y.marketPage=Math.max(0,Y.marketPage-1);render();break;case 'market-next':Y.marketPage++;render();break;case 'province':Y.marketPage=0;Y.province=b.dataset.code;Y.listQuery='';render();$('#province-results').focus({preventScroll:true});if(window.innerWidth<1100)$('#province-results').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});break;case 'clear-province':Y.province='';Y.marketPage=0;render();break;case 'place':Y.selected=id;location.hash='place/'+id;break;case 'target':{if(!canEdit())return;let had=!!Y.targets[id]&&!Y.targets[id].archived;if(Y.targets[id])Y.targets[id].archived=had;else Y.targets[id]={owner:Y.actor,status:'study',note:'',archived:false};emitEvent(had?'place.removed':'place.created','place',id,[{field:'target',before:had,after:!had}]);render();committed();break}case 'reset-draft':draft=structuredClone(Y.criteria);draftBase=Y.criteria.version;render();break;case 'apply-criteria':{if(!canEdit())return;if(draftBase!==Y.criteria.version){notify(tr('เกณฑ์ทีมเปลี่ยนแล้ว กดคืนค่าเกณฑ์ทีมก่อนลองอีกครั้ง','Team criteria changed. Reset to team settings before trying again.'));return}if(criteriaErrors(draft).length){notify(tr('ตรวจเกณฑ์ตัวเลขและเปิดสัญญาณ Demand อย่างน้อยหนึ่งกลุ่ม','Check numeric thresholds and enable at least one demand signal group.'));return}let changes=diffCriteria(Y.criteria,draft);if(!changes.length)return;const previous=Y.criteria,previousBase=draftBase,unsaved=structuredClone(draft);Y.criteria={...structuredClone(draft),version:Y.criteria.version+1};const event=emitEvent('criteria.updated','criteria','workspace-default',changes,{version:Y.criteria.version});if(!event){Y.criteria=previous;draft=unsaved;draftBase=previousBase;updateImpact();return}draft=structuredClone(Y.criteria);draftBase=Y.criteria.version;render();committed();break}case 'supply-tab':Y.poiTab=b.dataset.tab;Y.page=0;render();break;case 'poi-prev':Y.page=Math.max(0,Y.page-1);render();break;case 'poi-next':Y.page++;render();break;case 'new-poi':if(canEdit())location.hash='poi/new';break;case 'edit-poi':location.hash='poi/'+id;break;case 'archive-poi':case 'restore-poi':{if(!canEdit())return;let p=Y.pois.find(p=>p.id===id),before=p.archived;p.archived=action==='archive-poi';p.revision++;emitEvent(p.archived?'supply.archived':'supply.restored','supply',id,[{field:'archived',before,after:p.archived}],{area:p.area});render();committed();break}case 'place-branches':{let a=AREAS.find(x=>x.id===Y.selected);Y.poiQuery=provinceName(a.province)+' '+areaName(a.id);Y.poiQuery=areaName(a.id);Y.poiArea=a.id;Y.poiTab='all';Y.brandFilter='';Y.page=0;location.hash='supply';break}case 'clear-area':Y.poiArea='';Y.poiQuery='';render();break;case 'event-context':{let x=Y.events.find(x=>x.id===id);Y.read[Y.actor]=[...new Set([...(Y.read[Y.actor]||[]),id])];save();location.hash=x.entity==='criteria'?'criteria':x.entity==='supply'?'poi/'+x.entity_id:'place/'+x.entity_id;break}case 'jump-preview':$('#impact-preview').focus({preventScroll:true});$('#impact-preview').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});break;case 'read-all':Y.read[Y.actor]=Y.events.filter(x=>x.recipients.includes(Y.actor)).map(x=>x.id);save();render();break;case 'share':showShare();break;case 'close-share':$('#share-dialog').close();break;case 'preview-email':case 'preview-line':$('#channel-preview').textContent=tr('ตัวอย่างสำหรับ ','Preview for ')+(action==='preview-line'?'LINE':'Email')+': '+tr('ชวนดูทำเลนี้ด้วยเกณฑ์ทีม v','Review this location with team criteria v')+Y.criteria.version;break}});
document.addEventListener('submit',async e=>{if(!['poi-form','target-form'].includes(e.target.id))return;e.preventDefault();if(!canEdit())return;let form=e.target,data=Object.fromEntries(new FormData(form));if(form.id==='target-form'){let t=Y.targets[Y.selected],changes=['owner','status','note'].filter(k=>t[k]!==data[k]).map(k=>({field:k,before:t[k],after:data[k]}));if(!changes.length)return;t={...t,...data};Y.targets[Y.selected]=t;emitEvent('place.updated','place',Y.selected,changes);render();committed();return}let p=Y.pois.find(p=>p.id===form.dataset.id),fresh=!p;let error=msg=>{$('#form-error').textContent=msg};for(let k of Object.keys(data))if(typeof data[k]==='string')data[k]=data[k].trim();if((fresh&&!data.name)||!AREAS.some(a=>a.id===data.area))return error(tr('ระบุชื่อและทำเลให้ครบ','Enter a branch name and location.'));if(data.relation!=='unverified'&&!data.brand)return error(tr('ระบุแบรนด์ของสาขานี้','Enter the branch brand.'));if(data.relation==='unverified'&&data.status==='active')return error(tr('สาขาที่ยังไม่ทราบประเภทต้องเป็นรอตรวจสอบก่อน','An unverified relationship must remain pending.'));if(!!data.lat!==!!data.lng||data.lat&&(!Number.isFinite(+data.lat)||!Number.isFinite(+data.lng)||Math.abs(+data.lat)>90||Math.abs(+data.lng)>180))return error(tr('กรอกพิกัดทั้งคู่ให้ถูกต้อง','Enter a valid latitude and longitude pair.'));let verifying=data.status==='active'&&data.relation!=='unverified'&&(fresh||p.status!=='active'||p.relation==='unverified');if(verifying&&!data.note)return error(tr('เพิ่มหลักฐานหรือบันทึกการตรวจสอบก่อนยืนยัน','Add an evidence note before verifying this branch.'));let dup=Y.pois.find(x=>!x.archived&&x.id!==p?.id&&x.area===data.area&&!!data.name&&String(x.name||'').toLowerCase()===data.name.toLowerCase()&&String(x.brand||'').toLowerCase()===data.brand.toLowerCase());if(dup)return error(tr('มีสาขาชื่อนี้ แบรนด์นี้ ในทำเลเดียวกันแล้ว','This branch name and brand already exist in the location.'));if(data.relation==='own'&&data.brand.toUpperCase()!=='BANGCHAK')return error(tr('สาขาเราใน workspace นี้ต้องเป็นแบรนด์ BANGCHAK','Own branches in this workspace must use BANGCHAK.'));if(data.brand.toUpperCase()==='BANGCHAK'&&data.relation==='competitor')return error(tr('แบรนด์ BANGCHAK ต้องอยู่ในสาขาเรา','BANGCHAK belongs to our network.'));if(p&&+form.dataset.revision!==p.revision)return error(tr('รายการนี้ถูกแก้ไขแล้ว เปิดใหม่ก่อนบันทึก','This record changed. Reopen it before saving.'));data.name=data.name||null;data.lat=data.lat===''?null:+data.lat;data.lng=data.lng===''?null:+data.lng;let keys=['name','brand','relation','status','area','lat','lng','note'],changes=keys.filter(k=>p?.[k]!==data[k]).map(k=>({field:k,before:p?.[k]??null,after:data[k]}));
const photoId=form.dataset.id,photoDraft=YolkBranchPhotos.read(photoId);
if(photoDraft.busy||!photoDraft.ready)return error(tr('รอเตรียมรูปให้เสร็จก่อนบันทึก','Wait for the photos to finish preparing.'));
if(form.dataset.saving==='true')return;
if(!changes.length&&!photoDraft.dirty)return;
const branchId=p?.id||'poi-'+crypto.randomUUID(),actorAtSave=Y.actor,baseRevision=p?.revision;
const beforePhotos=p?.photos||photoDraft.savedPhotos||[];
const previousArea=p?.area,oldPois=structuredClone(Y.pois),oldEvents=structuredClone(Y.events);
let photoCommitted=false,workspaceCommitted=false;form.dataset.saving='true';const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
try {
  const photoResult=photoDraft.dirty?await YolkBranchPhotos.commit(photoId,branchId):photoDraft;
  photoCommitted=photoDraft.dirty;
  if(!canEdit()||Y.actor!==actorAtSave)throw Error(tr('ผู้ใช้เปลี่ยนแล้ว กรุณาตรวจสิทธิ์และบันทึกใหม่','The active user changed. Check access and save again.'));
  if(p&&p.revision!==baseRevision)throw Error(tr('สาขานี้ถูกแก้ไขระหว่างบันทึก เปิดใหม่เพื่อตรวจข้อมูล','This branch changed while saving. Reopen to review it.'));
  if(photoDraft.dirty){data.photos=photoResult.photos;changes.push({field:'photos',before:beforePhotos.map(({id,title,cover})=>({id,title,cover})),after:photoResult.photos.map(({id,title,cover})=>({id,title,cover}))})}
  if(fresh){p={id:branchId,...data,revision:1,archived:false,sourceDataset:'workspace',operatingStatus:'not_independently_verified'};Y.pois.push(p)}else{Object.assign(p,data);p.revision++}
  const event=emitEvent(fresh?'supply.created':verifying?'supply.verified':'supply.updated','supply',p.id,changes,{area:p.area,previousArea});
  if(!event){Y.pois=oldPois;Y.events=oldEvents;throw Error(tr('บันทึกข้อมูลสาขาไม่สำเร็จ กรุณาลองอีกครั้ง','Could not save the branch. Please try again.'))}
  workspaceCommitted=true;YolkBranchPhotos.finalizeCommit(branchId);location.hash='poi/'+p.id;render();committed();
} catch(err){if(photoCommitted&&!workspaceCommitted){try{await YolkBranchPhotos.rollbackCommit(branchId)}catch(rollbackError){err.message+=' · '+rollbackError.message}}error(err.message||tr('บันทึกไม่สำเร็จ กรุณาลองอีกครั้ง','Save failed. Please try again.'))}
finally{form.dataset.saving='false';if(submit)submit.disabled=!canEdit()}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#content').focus({preventScroll:true})});render();
